export type LayerId =
  | 'provinces'
  | 'mountains'
  | 'lakes'
  | 'plains'
  | 'rivers'
  | 'coasts'
  | 'geology'
  | 'soil'
  | 'minerals'
  | 'projects'
  | 'transport';

export type TopicStatus = 'new' | 'studying' | 'review' | 'weak' | 'done';

export type MapItem = {
  id: string;
  name: string;
  layer: Exclude<LayerId, 'provinces'>;
  subtype: string;
  subtypeLabel: string;
  provinces: string[];
  tags?: string[];
  elevation?: string;
  description: string;
  examTip?: string;
  /** İçeriğin dayandığı kaynak referansı (opsiyonel; yoksa katman varsayılanı kullanılır). */
  source?: string;
};

